import type { Question } from '../../lib/types'

export const dr_strategies_questions: Question[] = [
  { id: 'd2-dr-001', domain: 2, topics: ['DR', 'RTO', 'RPO', 'strategies'], type: 'single', stem: 'A company requires an RTO of less than 1 minute and RPO of near-zero for their critical payment system. Which DR strategy meets these requirements?', options: [{ id: 'A', text: 'Backup and Restore — restore from backups in another region' }, { id: 'B', text: 'Pilot Light — minimal infrastructure in standby' }, { id: 'C', text: 'Multi-Site Active-Active — full production environment in multiple regions simultaneously' }, { id: 'D', text: 'Warm Standby — scaled-down but functional environment in standby' }], correct: ['C'], explanation: 'Active-Active (multi-site) has near-zero RPO because all regions process transactions simultaneously, and RTO under 1 minute because failover is just routing traffic to the healthy region. It\'s the most expensive but provides the best RTO/RPO.', distractors: { A: 'Backup and Restore has RTO of hours to days — far exceeds 1-minute requirement.', B: 'Pilot Light requires scaling up resources on failover — typically 10-30 minutes RTO.', D: 'Warm Standby can achieve RTO of minutes (5-15 min) but may not reliably hit under 1 minute.' } },
  { id: 'd2-dr-002', domain: 2, topics: ['DR', 'backup restore', 'cost'], type: 'single', stem: 'A startup has minimal budget but needs disaster recovery for a non-critical internal application. They accept RTO and RPO of hours. Which DR strategy is most cost-effective?', options: [{ id: 'A', text: 'Active-Active multi-site' }, { id: 'B', text: 'Warm Standby' }, { id: 'C', text: 'Backup and Restore — lowest cost, backs up data to S3 in another region, restore in case of disaster' }, { id: 'D', text: 'Pilot Light' }], correct: ['C'], explanation: 'Backup and Restore is the cheapest DR strategy. Data (backups, AMIs, CloudFormation templates) is stored in S3 in another region. Recovery requires launching resources from scratch — RTO/RPO measured in hours. No standby infrastructure costs.', distractors: { A: 'Active-Active is the most expensive — overkill for non-critical applications.', B: 'Warm Standby has ongoing costs for the scaled-down running environment.', D: 'Pilot Light maintains core services running — more expensive than pure backup and restore.' } },
  { id: 'd2-dr-003', domain: 2, topics: ['DR', 'pilot light', 'definition'], type: 'single', stem: 'A company uses the Pilot Light DR strategy. Which resources are kept running in the DR region?', options: [{ id: 'A', text: 'Full production replica at reduced capacity' }, { id: 'B', text: 'Only the most critical core components (e.g., database replication, critical services) — the rest must be provisioned on failover' }, { id: 'C', text: 'No resources — everything is restored from backup' }, { id: 'D', text: 'All production resources at 100% capacity' }], correct: ['B'], explanation: 'Pilot Light keeps only critical core services running in the DR region — typically the database (continuously replicated) and any mission-critical services. Non-critical resources are provisioned quickly using IaC during failover.', distractors: { A: 'Reduced capacity replica is Warm Standby — Pilot Light is minimal, not reduced capacity.', C: 'No running resources is Backup and Restore — Pilot Light keeps the "pilot light" of core services running.', D: 'Full capacity is Active-Active — the most expensive strategy.' } },
  { id: 'd2-dr-004', domain: 2, topics: ['DR', 'Route 53', 'failover', 'health check'], type: 'single', stem: 'A company has production in us-east-1 and a DR environment in eu-west-1. Route 53 should automatically redirect all traffic to eu-west-1 when us-east-1 fails health checks. What routing policy and feature combination achieves this?', options: [{ id: 'A', text: 'Route 53 latency routing with health checks' }, { id: 'B', text: 'Route 53 failover routing with health checks on the primary record' }, { id: 'C', text: 'Route 53 weighted routing (100/0)' }, { id: 'D', text: 'Route 53 geolocation routing' }], correct: ['B'], explanation: 'Route 53 failover routing + health checks: the primary record (us-east-1) has a health check attached. When the health check fails, Route 53 automatically serves the secondary record (eu-west-1). This is the canonical Route 53 DR pattern.', distractors: { A: 'Latency routing chooses the lowest-latency endpoint — doesn\'t do active-passive failover based on health checks.', C: '100/0 weighted routing always sends to us-east-1 — won\'t failover automatically.', D: 'Geolocation routing routes based on user location — not based on health checks.' } },
  { id: 'd2-dr-005', domain: 2, topics: ['DR', 'Aurora Global Database', 'RTO RPO'], type: 'single', stem: 'A company using Aurora Global Database needs to failover to a secondary region. What are the approximate RTO and RPO?', options: [{ id: 'A', text: 'RTO: 24 hours, RPO: 1 hour' }, { id: 'B', text: 'RTO: <1 minute, RPO: 0 (no data loss)' }, { id: 'C', text: 'RTO: <1 minute, RPO: <1 second (Aurora global storage replication lag)' }, { id: 'D', text: 'RTO: 30 minutes, RPO: 5 minutes' }], correct: ['C'], explanation: 'Aurora Global Database uses storage-level replication with <1 second lag (RPO). Managed failover promotes the secondary to primary in typically under 1 minute (RTO). This meets the most aggressive DR requirements for relational databases.', distractors: { A: 'These figures are for Backup and Restore — far worse than Aurora Global Database.', B: 'Zero RPO is not achievable with asynchronous replication — there\'s a small lag (<1 sec).', D: 'These would be appropriate for standard CRR/read replica DR — Aurora Global Database is much faster.' } },
  { id: 'd2-dr-006', domain: 2, topics: ['DR', 'elastic disaster recovery', 'DRS'], type: 'single', stem: 'A company wants to replicate on-premises servers to AWS continuously and be able to recover them quickly in AWS during a disaster. What AWS service provides this?', options: [{ id: 'A', text: 'AWS Backup' }, { id: 'B', text: 'AWS Elastic Disaster Recovery (DRS) — continuous block-level replication to AWS, launch recovery instances in minutes' }, { id: 'C', text: 'AWS Storage Gateway' }, { id: 'D', text: 'AWS DataSync' }], correct: ['B'], explanation: 'AWS DRS (formerly CloudEndure Disaster Recovery) continuously replicates block storage from on-premises or cloud servers to AWS. On failover, recovery instances are launched in minutes from the replicated state.', distractors: { A: 'AWS Backup manages backups and snapshots — not continuous server replication for DR.', C: 'Storage Gateway provides hybrid cloud storage — not server replication for DR.', D: 'DataSync moves file data between on-premises and AWS — not a DR tool for full server recovery.' } },
  { id: 'd2-dr-007', domain: 2, topics: ['DR', 'warm standby', 'scaling'], type: 'single', stem: 'A company uses Warm Standby DR. A disaster occurs and failover is initiated. What must happen to the DR environment to handle full production traffic?', options: [{ id: 'A', text: 'Nothing — the DR environment is already at full capacity' }, { id: 'B', text: 'Scale up the DR environment (increase Auto Scaling group sizes, promote DB read replica, update DNS)' }, { id: 'C', text: 'Restore from backups in the DR region' }, { id: 'D', text: 'Contact AWS Support to launch additional resources' }], correct: ['B'], explanation: 'Warm Standby runs at minimum capacity (e.g., ASG min=1, t3.micro). On failover: scale up ASG to production sizes, promote the read replica/standby to primary, update Route 53 to point to DR region, switch DNS. This is faster than Pilot Light since the environment is already running.', distractors: { A: 'Active-Active is at full capacity — Warm Standby is at reduced capacity by definition.', C: 'Restoring from backups is Backup and Restore strategy — Warm Standby has a live (minimal) environment.', D: 'No AWS Support involvement needed — scaling is done via IaC/Auto Scaling.' } },
  { id: 'd2-dr-008', domain: 2, topics: ['DR', 'S3 CRR', 'backup'], type: 'single', stem: 'As part of a DR strategy, a company needs to ensure all S3 data is replicated to another region automatically. What is the appropriate approach?', options: [{ id: 'A', text: 'Daily S3 sync scripts' }, { id: 'B', text: 'S3 Cross-Region Replication (CRR) — automatically replicates new and updated objects to the DR region' }, { id: 'C', text: 'Copy all objects manually before a disaster' }, { id: 'D', text: 'S3 Transfer Acceleration' }], correct: ['B'], explanation: 'S3 CRR continuously replicates objects to a destination bucket in another region. For DR purposes, enable Delete Marker Replication and Replication Time Control (for 15-minute SLA) if needed. Requires versioning on both buckets.', distractors: { A: 'Daily sync scripts have a 24-hour RPO and require maintenance.', C: 'Manual copying before a disaster is not a valid DR strategy — disasters are unpredictable.', D: 'Transfer Acceleration speeds uploads to a single bucket — not cross-region replication.' } },
  { id: 'd2-dr-009', domain: 2, topics: ['DR', 'RDS', 'cross-region', 'read replica'], type: 'single', stem: 'A company has RDS MySQL in us-east-1 and wants a DR database in eu-west-1 that is continuously synchronized. On failover, the EU database should become the primary. What is the architecture?', options: [{ id: 'A', text: 'RDS Multi-AZ in us-east-1' }, { id: 'B', text: 'RDS Cross-Region Read Replica in eu-west-1 — on failover, promote the read replica to standalone primary' }, { id: 'C', text: 'RDS snapshot copy to eu-west-1' }, { id: 'D', text: 'AWS DMS continuous replication to eu-west-1' }], correct: ['B'], explanation: 'Cross-region read replicas provide continuous async replication. On failover, promote the read replica to a standalone RDS instance (primary). Update the application connection string to the new primary. RPO is the replication lag (seconds to minutes).', distractors: { A: 'Multi-AZ is within a single region — doesn\'t provide cross-region DR.', C: 'Snapshot copies are point-in-time — not continuously synchronized.', D: 'DMS replication works but is more complex to manage vs. native RDS cross-region replicas.' } },
  { id: 'd2-dr-010', domain: 2, topics: ['DR', 'EC2', 'AMI', 'cross-region'], type: 'single', stem: 'A company\'s DR strategy requires the ability to launch EC2 instances in a secondary region within 15 minutes. What should be prepared in advance?', options: [{ id: 'A', text: 'Keep EC2 instances running in the secondary region (expensive)' }, { id: 'B', text: 'Copy AMIs to the secondary region and have CloudFormation/Terraform ready to deploy — launch from AMIs in <15 min' }, { id: 'C', text: 'Use EC2 Spot Instances for DR' }, { id: 'D', text: 'Contact AWS Support to reserve capacity' }], correct: ['B'], explanation: 'Pre-copying AMIs to the DR region and having IaC templates ready enables rapid launch. AMI copy takes time — by having them pre-staged, instances can launch within the RTO window. Test the runbook regularly.', distractors: { A: 'Running instances 24/7 in standby is Warm Standby — expensive if not needed.', C: 'Spot Instances can be interrupted — not reliable for DR.', D: 'Reserved capacity can be reserved proactively (Capacity Reservations) — not via Support.' } },
  { id: 'd2-dr-011', domain: 2, topics: ['DR', 'chaos engineering', 'testing'], type: 'single', stem: 'A company wants to test their DR procedures and identify weaknesses before a real disaster. Which AWS service helps simulate infrastructure failures?', options: [{ id: 'A', text: 'AWS Config' }, { id: 'B', text: 'AWS Fault Injection Simulator (FIS) — controlled fault injection to test DR procedures and resilience' }, { id: 'C', text: 'AWS CloudTrail' }, { id: 'D', text: 'AWS Trusted Advisor' }], correct: ['B'], explanation: 'AWS FIS enables chaos engineering experiments by injecting controlled failures (terminate EC2 instances, throttle CPU, inject latency). This tests DR runbooks and identifies gaps before actual disasters.', distractors: { A: 'AWS Config tracks configuration compliance — not failure simulation.', C: 'CloudTrail logs API calls — not failure simulation.', D: 'Trusted Advisor provides recommendations — not failure injection testing.' } },
  { id: 'd2-dr-012', domain: 2, topics: ['DR', 'data backup', 'AWS Backup'], type: 'single', stem: 'A company needs centralized backup management across EC2, RDS, EFS, DynamoDB, and EBS across multiple AWS accounts. What service centralizes this?', options: [{ id: 'A', text: 'Separate backup solutions per service' }, { id: 'B', text: 'AWS Backup — centralized backup service supporting multiple AWS services with cross-account and cross-region backup' }, { id: 'C', text: 'S3 Lifecycle rules' }, { id: 'D', text: 'EC2 snapshots for all services' }], correct: ['B'], explanation: 'AWS Backup provides centralized backup management with policies (backup plans) applied across EC2, RDS, Aurora, DynamoDB, EFS, FSx, and EBS. Supports cross-region and cross-account backup for DR.', distractors: { A: 'Service-specific backups work but require separate management — AWS Backup centralizes via a single policy.', C: 'S3 lifecycle rules manage S3 object tiers — not backups for other services.', D: 'EC2 snapshots are EBS-specific — can\'t back up RDS, EFS, DynamoDB, etc.' } },
  { id: 'd2-dr-013', domain: 2, topics: ['DR', 'DynamoDB', 'global tables'], type: 'single', stem: 'A company uses DynamoDB and requires a multi-region active-active setup where writes can occur in any region and are automatically synchronized. What DynamoDB feature enables this?', options: [{ id: 'A', text: 'DynamoDB Cross-Region Read Replicas' }, { id: 'B', text: 'DynamoDB Global Tables — multi-region, multi-active replication with automatic conflict resolution' }, { id: 'C', text: 'DynamoDB Streams' }, { id: 'D', text: 'DynamoDB multi-AZ deployment' }], correct: ['B'], explanation: 'DynamoDB Global Tables provides active-active multi-region replication. Write in any region; changes replicate to all other regions within seconds using last-writer-wins conflict resolution. Typically <1 second replication lag.', distractors: { A: 'DynamoDB doesn\'t have a "read replica" concept like RDS — Global Tables is the multi-region solution.', C: 'DynamoDB Streams capture item changes — used as the replication mechanism for Global Tables but not by itself a DR solution.', D: 'DynamoDB is highly available within a region automatically — Global Tables extends this across regions.' } },
  { id: 'd2-dr-014', domain: 2, topics: ['DR', 'Availability Zone', 'fault domains'], type: 'single', stem: 'A company wants their application to survive a single Availability Zone failure with zero data loss and automatic failover. What is the minimum architecture requirement?', options: [{ id: 'A', text: 'Single EC2 instance with enhanced monitoring' }, { id: 'B', text: 'Multi-AZ deployment: EC2 across at least 2 AZs with Auto Scaling, and RDS Multi-AZ — single AZ failure causes automatic failover' }, { id: 'C', text: 'Multi-Region Active-Active' }, { id: 'D', text: 'EC2 in a placement group' }], correct: ['B'], explanation: 'Multi-AZ within a region protects against AZ failures. RDS Multi-AZ automatically fails over to the standby. Auto Scaling across AZs automatically launches replacements. This is the baseline HA architecture for single-region, multi-AZ resilience.', distractors: { A: 'A single EC2 instance is a single point of failure — doesn\'t survive AZ failure.', C: 'Multi-Region Active-Active is required for regional failures — more expensive than needed for AZ-level resilience.', D: 'Placement groups (cluster) actually concentrate instances in the same AZ — worse for AZ failure resilience.' } },
  { id: 'd2-dr-015', domain: 2, topics: ['DR', 'EBS snapshots', 'cross-region'], type: 'single', stem: 'A company\'s DR strategy requires EBS volumes to be available in a secondary region. How are EBS snapshots made available cross-region?', options: [{ id: 'A', text: 'EBS volumes automatically replicate cross-region' }, { id: 'B', text: 'Copy EBS snapshots to the secondary region — snapshots can be copied across regions' }, { id: 'C', text: 'Use S3 to replicate EBS data' }, { id: 'D', text: 'EBS snapshots are global and available in all regions automatically' }], correct: ['B'], explanation: 'EBS snapshots can be copied to other regions using the CopySnapshot API or console. Use AWS Backup with cross-region copy rules to automate this for DR. The copied snapshot can be used to restore EBS volumes in the target region.', distractors: { A: 'EBS volumes are AZ-scoped resources — no automatic cross-region replication.', C: 'S3 stores snapshots internally but you use the EBS snapshot copy mechanism, not direct S3 manipulation.', D: 'EBS snapshots are regional — not automatically global.' } },
  { id: 'd2-dr-016', domain: 2, topics: ['DR', 'RPO definition'], type: 'single', stem: 'What does Recovery Point Objective (RPO) measure in disaster recovery planning?', options: [{ id: 'A', text: 'The time required to restore systems after a disaster' }, { id: 'B', text: 'The maximum acceptable data loss measured in time — how far back in time your recovery point can be' }, { id: 'C', text: 'The cost of maintaining the DR environment' }, { id: 'D', text: 'The maximum number of failed requests before failover triggers' }], correct: ['B'], explanation: 'RPO is the maximum acceptable amount of data loss measured in time. If RPO=1 hour, you can tolerate losing up to 1 hour of data. Lower RPO requires more frequent backups or continuous replication, which costs more.', distractors: { A: 'Time to restore is RTO (Recovery Time Objective) — not RPO.', C: 'DR cost is not what RPO measures.', D: 'Request failure thresholds are related to availability, not RPO definition.' } },
  { id: 'd2-dr-017', domain: 2, topics: ['DR', 'RTO definition'], type: 'single', stem: 'What does Recovery Time Objective (RTO) measure?', options: [{ id: 'A', text: 'Maximum acceptable data loss' }, { id: 'B', text: 'Maximum time the system can be down before business impact is unacceptable — time to restore service' }, { id: 'C', text: 'Time between backups' }, { id: 'D', text: 'Time to replicate data to another region' }], correct: ['B'], explanation: 'RTO is the maximum acceptable downtime — how long can your system be unavailable? Lower RTO requires faster failover mechanisms (warm standby, active-active) which cost more to maintain.', distractors: { A: 'Maximum data loss is RPO — RTO is about downtime duration.', C: 'Time between backups determines RPO — not RTO.', D: 'Replication time affects RPO (data currency) — RTO is about service restoration time.' } },
  { id: 'd2-dr-018', domain: 2, topics: ['DR', 'Lambda', 'serverless DR'], type: 'single', stem: 'A company runs a serverless application using Lambda, API Gateway, and DynamoDB. What is a key advantage for DR purposes?', options: [{ id: 'A', text: 'Serverless applications have no DR requirements' }, { id: 'B', text: 'Serverless infrastructure deploys in seconds via IaC — no EC2 provisioning required during failover, significantly reducing RTO' }, { id: 'C', text: 'Lambda is region-specific and cannot failover' }, { id: 'D', text: 'DynamoDB replication is automatic across all regions by default' }], correct: ['B'], explanation: 'Serverless apps have minimal infrastructure state — Lambda code, API Gateway configs, and DynamoDB tables can be deployed in seconds via CloudFormation/SAM in the DR region. With DynamoDB Global Tables, data is already replicated. RTO can be minutes or even seconds.', distractors: { A: 'Serverless apps still require DR planning — regional failures affect Lambda and API Gateway too.', C: 'Lambda functions can be deployed in any region — cross-region DR is very straightforward for serverless.', D: 'DynamoDB Global Tables must be explicitly configured — DynamoDB is not automatically replicated globally.' } },
  { id: 'd2-dr-019', domain: 2, topics: ['DR', 'SQS', 'decoupling', 'resilience'], type: 'single', stem: 'During a regional failure, SQS messages must not be lost. The DR region should process the SQS messages when the primary region recovers or when traffic is redirected. How can SQS contribute to resilience?', options: [{ id: 'A', text: 'SQS queues automatically replicate across regions' }, { id: 'B', text: 'SQS durably stores messages for up to 14 days — decouple producers from consumers so messages survive temporary consumer failures' }, { id: 'C', text: 'SQS automatically fails over to the DR region' }, { id: 'D', text: 'SQS messages are lost if the consumer fails' }], correct: ['B'], explanation: 'SQS stores messages for up to 14 days. If consumers in the primary region fail, messages wait in the queue. When DR consumers come online (in the same or another region via cross-region queues), they process the backlog. This decoupling is a key resilience pattern.', distractors: { A: 'SQS queues are regional — they don\'t automatically replicate cross-region.', C: 'SQS doesn\'t automatically failover — it stores messages until consumed.', D: 'SQS provides at-least-once delivery — messages are retained until successfully processed.' } },
  { id: 'd2-dr-020', domain: 2, topics: ['DR', 'CloudFormation', 'IaC', 'recovery'], type: 'single', stem: 'A company wants to recover their entire infrastructure in a secondary region in case of a regional disaster. What is the most reliable way to ensure infrastructure can be quickly rebuilt?', options: [{ id: 'A', text: 'Document all infrastructure in a runbook' }, { id: 'B', text: 'Use Infrastructure as Code (CloudFormation/Terraform) — deploy the stack in the DR region to recreate all resources' }, { id: 'C', text: 'Keep screenshots of the AWS console configuration' }, { id: 'D', text: 'Export all infrastructure settings to CSV' }], correct: ['B'], explanation: 'IaC templates (CloudFormation, CDK, Terraform) can deploy the complete infrastructure in any region in minutes. This is a fundamental DR best practice — runbooks are prone to human error and outdated documentation.', distractors: { A: 'Runbooks depend on human execution accuracy and staying current — IaC is more reliable and automated.', C: 'Screenshots don\'t enable automated recovery and become stale as infrastructure changes.', D: 'CSV exports require manual re-creation — IaC automates deployment.' } },
  { id: 'd2-dr-021', domain: 2, topics: ['DR', 'cost optimization', 'strategy comparison'], type: 'single', stem: 'Rank these DR strategies from lowest to highest cost (and inversely from highest to lowest RTO):', options: [{ id: 'A', text: 'Active-Active > Warm Standby > Pilot Light > Backup and Restore' }, { id: 'B', text: 'Backup and Restore < Pilot Light < Warm Standby < Active-Active' }, { id: 'C', text: 'Pilot Light < Backup and Restore < Active-Active < Warm Standby' }, { id: 'D', text: 'Warm Standby < Pilot Light < Active-Active < Backup and Restore' }], correct: ['B'], explanation: 'The DR spectrum from lowest to highest cost (and lowest to highest RTO): Backup & Restore (cheapest, hours RTO) → Pilot Light (minimal infrastructure) → Warm Standby (scaled-down running environment) → Active-Active (most expensive, lowest RTO).', distractors: { A: 'Active-Active is the highest cost — the order is correct in the wrong direction.', C: 'Pilot Light costs more than Backup and Restore (Pilot Light keeps some resources running).', D: 'The order is wrong — Backup and Restore is cheapest with highest RTO.' } },
  { id: 'd2-dr-022', domain: 2, topics: ['DR', 'Availability Zones', 'single region'], type: 'single', stem: 'An application uses a single EC2 instance in one AZ. An AZ outage causes a 4-hour outage. What is the minimum change to make the application survive an AZ failure with automatic recovery?', options: [{ id: 'A', text: 'Enable detailed monitoring on the EC2 instance' }, { id: 'B', text: 'Place the EC2 instance in an Auto Scaling group spanning multiple AZs — unhealthy instance replaced in a healthy AZ' }, { id: 'C', text: 'Enable Elastic IP for the EC2 instance' }, { id: 'D', text: 'Enable Multi-AZ for EC2' }], correct: ['B'], explanation: 'Auto Scaling groups with desired capacity=1 spanning multiple AZs: if the AZ fails, ASG detects the unhealthy instance and launches a replacement in a healthy AZ. The EBS volume or data source must also be accessible from the new AZ (e.g., use EFS or RDS instead of local EBS).', distractors: { A: 'Detailed monitoring improves detection but doesn\'t prevent or recover from AZ failures.', C: 'Elastic IP doesn\'t help if the AZ itself is down — the instance needs to be in a different AZ.', D: 'Multi-AZ is an RDS concept — EC2 uses Auto Scaling groups for multi-AZ resilience.' } },
  { id: 'd2-dr-023', domain: 2, topics: ['DR', 'data recovery', 'EFS'], type: 'single', stem: 'An application requires shared file storage accessible from EC2 instances in multiple AZs within a single region. If one AZ fails, instances in other AZs should continue accessing the file data. What storage service should be used?', options: [{ id: 'A', text: 'EBS volume shared across instances' }, { id: 'B', text: 'Amazon EFS (Elastic File System) — regional storage accessible from all AZs within a region via mount targets' }, { id: 'C', text: 'S3 with mounted FUSE driver' }, { id: 'D', text: 'Instance store volumes' }], correct: ['B'], explanation: 'EFS provides regional NFS file storage with mount targets in each AZ. If one AZ fails, instances in other AZs continue accessing the same EFS file system through mount targets in their respective AZs.', distractors: { A: 'EBS volumes are AZ-scoped — cannot be shared across AZs and not accessible if that AZ fails.', C: 'S3 with FUSE has performance and consistency limitations — EFS is designed for file system workloads.', D: 'Instance store is ephemeral local storage that is lost when the instance stops — no sharing across instances.' } },
  { id: 'd2-dr-024', domain: 2, topics: ['DR', 'CloudWatch', 'alarms', 'auto recovery'], type: 'single', stem: 'An EC2 instance hosts a critical application. If the underlying hardware fails, the instance should automatically recover without data loss and retain its private IP. What feature provides this?', options: [{ id: 'A', text: 'Auto Scaling group with minimum 1 instance' }, { id: 'B', text: 'EC2 Auto Recovery — CloudWatch alarm on StatusCheckFailed:System triggers instance recovery on new hardware' }, { id: 'C', text: 'EBS Multi-Attach' }, { id: 'D', text: 'Elastic IP reassignment' }], correct: ['B'], explanation: 'EC2 Auto Recovery (via CloudWatch alarm action) automatically recovers an instance on a different host while retaining the instance ID, private IP, Elastic IP, and all EBS volumes. The instance must use EBS-backed storage (not instance store).', distractors: { A: 'ASG replaces terminated instances with new ones — they get new instance IDs and may get different IPs.', C: 'EBS Multi-Attach allows multiple instances to mount one volume — not a recovery mechanism.', D: 'Elastic IP reassignment is manual — not automatic recovery.' } },
  { id: 'd2-dr-025', domain: 2, topics: ['DR', 'SQS', 'decoupling at scale'], type: 'single', stem: 'A company processes orders from multiple services. During high traffic, some processing services fail and fall behind. Which DR and resilience pattern prevents cascading failures?', options: [{ id: 'A', text: 'Synchronous processing with retry loops' }, { id: 'B', text: 'Asynchronous processing with SQS queues — services fail independently, queues buffer messages, system self-heals' }, { id: 'C', text: 'Increase instance sizes' }, { id: 'D', text: 'Enable Multi-AZ for all services' }], correct: ['B'], explanation: 'SQS decouples services so they fail independently. If an order processor fails, messages queue up (no cascade to the API layer). When the processor recovers, it drains the backlog. This is the "circuit breaker" pattern — queues absorb failure impacts.', distractors: { A: 'Synchronous retry loops propagate failures upstream — the order API waits and may also fail.', C: 'Larger instances help with load but don\'t prevent cascading failures — asynchronous patterns do.', D: 'Multi-AZ provides HA within AWS — doesn\'t prevent service-level cascading failures.' } },
  { id: 'd2-dr-026', domain: 2, topics: ['DR', 'RDS', 'snapshot', 'restore'], type: 'single', stem: 'What happens to an RDS instance when it is restored from a snapshot?', options: [{ id: 'A', text: 'The original instance is replaced in-place' }, { id: 'B', text: 'A new RDS instance is created — the original instance continues running until manually terminated' }, { id: 'C', text: 'Only the data changes — instance settings remain the same' }, { id: 'D', text: 'The snapshot restore overwrites data in the existing instance' }], correct: ['B'], explanation: 'Restoring from an RDS snapshot always creates a NEW DB instance. The original instance is not affected. After restoration, the application connection string must be updated to point to the new instance endpoint.', distractors: { A: 'Restore is not an in-place operation — it creates a new instance.', C: 'A completely new instance with new endpoint and default parameter group is created.', D: 'Snapshot restore never overwrites an existing instance.' } },
  { id: 'd2-dr-027', domain: 2, topics: ['DR', 'multi-region', 'stateless'], type: 'single', stem: 'A company wants to design their application to be easily deployable in multiple regions for DR. What architectural principle minimizes the difficulty of deploying to a new region?', options: [{ id: 'A', text: 'Store all application state locally on EC2 instances' }, { id: 'B', text: 'Design stateless application tiers — store state in managed services (RDS, DynamoDB, ElastiCache) that can be replicated' }, { id: 'C', text: 'Use one large EC2 instance for everything' }, { id: 'D', text: 'Avoid using IaC to maintain manual control' }], correct: ['B'], explanation: 'Stateless application tiers (Lambda, ECS, EC2 with no local state) are trivially redeployable — just run the same container/code in a new region. State lives in managed services that have cross-region replication capabilities (DynamoDB Global Tables, Aurora Global DB, S3 CRR).', distractors: { A: 'Local state on EC2 is lost on instance replacement and can\'t be moved to another region.', C: 'A monolithic large instance creates a single point of failure and is harder to replicate.', D: 'IaC is essential for repeatable multi-region deployments — avoiding it makes DR harder.' } },
  { id: 'd2-dr-028', domain: 2, topics: ['DR', 'recovery drills', 'runbooks'], type: 'single', stem: 'A company has a DR plan but has never tested it. What is the biggest risk of an untested DR plan?', options: [{ id: 'A', text: 'DR plans don\'t require testing if they use AWS managed services' }, { id: 'B', text: 'The actual RTO/RPO may be significantly worse than planned — untested runbooks have gaps, outdated configurations, and missing steps' }, { id: 'C', text: 'Testing DR plans can cause real outages' }, { id: 'D', text: 'DR testing is optional for non-critical applications' }], correct: ['B'], explanation: 'Untested DR plans often fail in practice due to outdated runbooks, undocumented dependencies, missing IAM permissions, out-of-date AMIs/snapshots, and human errors under pressure. Regular testing (game days, chaos engineering) validates actual RTO/RPO.', distractors: { A: 'Even AWS managed services require application-level DR procedures — connection string updates, data validation, etc.', C: 'DR drills should be done in non-production or with proper isolation — testing doesn\'t require real production outages.', D: 'DR testing is recommended for ALL applications, even non-critical ones.' } },
  { id: 'd2-dr-029', domain: 2, topics: ['DR', 'Health Dashboard', 'AWS Health'], type: 'single', stem: 'A company needs to be notified when AWS services they use are experiencing issues that could affect their DR planning. What service provides proactive notifications?', options: [{ id: 'A', text: 'AWS CloudWatch alarms' }, { id: 'B', text: 'AWS Health (formerly Personal Health Dashboard) — personalized service event notifications for YOUR resources' }, { id: 'C', text: 'AWS Service Health Dashboard' }, { id: 'D', text: 'AWS Config' }], correct: ['B'], explanation: 'AWS Health provides personalized notifications about AWS events that specifically affect your accounts and resources (not just general AWS service status). Integrate with EventBridge to automate responses.', distractors: { A: 'CloudWatch alarms monitor your own metrics — not AWS service health events.', C: 'Service Health Dashboard shows general AWS status — AWS Health shows events affecting YOUR resources specifically.', D: 'AWS Config tracks configuration compliance — not AWS service health.' } },
  { id: 'd2-dr-030', domain: 2, topics: ['DR', 'Lambda', 'Resilience Hub'], type: 'single', stem: 'A company wants AWS to automatically assess their application\'s resilience against defined RTO and RPO targets and identify gaps. What AWS service provides this?', options: [{ id: 'A', text: 'AWS Trusted Advisor' }, { id: 'B', text: 'AWS Resilience Hub — defines RTO/RPO targets, assesses application resilience, identifies gaps, suggests improvements' }, { id: 'C', text: 'AWS Config' }, { id: 'D', text: 'AWS Security Hub' }], correct: ['B'], explanation: 'AWS Resilience Hub lets you define RTO/RPO targets and automatically assesses your application architecture against them. It identifies resilience gaps, provides recommendations (like adding Multi-AZ), and generates runbooks.', distractors: { A: 'Trusted Advisor provides general best practice recommendations — not RTO/RPO-specific resilience assessment.', C: 'AWS Config checks resource configuration compliance — not application-level resilience against RTO/RPO.', D: 'Security Hub aggregates security findings — not DR resilience assessment.' } },
  { id: 'd2-dr-031', domain: 2, topics: ['DR', 'VPC', 'Transit Gateway', 'failover networking'], type: 'single', stem: 'A company has Direct Connect to on-premises and wants network failover to VPN if Direct Connect fails. What provides automatic failover between Direct Connect and VPN?', options: [{ id: 'A', text: 'Route 53 failover routing' }, { id: 'B', text: 'Configure both Direct Connect and Site-to-Site VPN — use BGP routing so VPN is backup path when Direct Connect fails' }, { id: 'C', text: 'AWS Global Accelerator' }, { id: 'D', text: 'CloudFront caching' }], correct: ['B'], explanation: 'The resilient hybrid network pattern: Direct Connect as primary, Site-to-Site VPN as backup. Configure BGP metrics so Direct Connect is preferred. When Direct Connect fails, BGP automatically reroutes through VPN. Can also use Transit Gateway to simplify routing.', distractors: { A: 'Route 53 handles DNS-level routing — not network-level Direct Connect/VPN failover.', C: 'Global Accelerator is for application-level routing via the AWS network — not on-premises connectivity failover.', D: 'CloudFront is a CDN — not relevant to on-premises network connectivity.' } },
  { id: 'd2-dr-032', domain: 2, topics: ['DR', 'ElastiCache', 'global datastore'], type: 'single', stem: 'A company uses ElastiCache Redis for session caching and needs the cache data to be available in a secondary region for DR. What ElastiCache feature supports cross-region replication?', options: [{ id: 'A', text: 'ElastiCache Multi-AZ' }, { id: 'B', text: 'ElastiCache Global Datastore — read replicas in secondary regions with low-latency replication' }, { id: 'C', text: 'ElastiCache backup and restore to secondary region' }, { id: 'D', text: 'ElastiCache doesn\'t support cross-region replication' }], correct: ['B'], explanation: 'ElastiCache Global Datastore for Redis enables cross-region replication. A primary cluster in one region replicates to read-only secondary clusters in other regions. On failover, promote the secondary to primary.', distractors: { A: 'Multi-AZ provides HA within a single region — not cross-region DR.', C: 'Backup and restore has an RPO of hours — Global Datastore provides continuous replication.', D: 'ElastiCache Global Datastore does support cross-region replication.' } },
  { id: 'd2-dr-033', domain: 2, topics: ['DR', 'stateful applications', 'session management'], type: 'single', stem: 'During failover to a DR region, user sessions stored in EC2 memory are lost. Users are logged out and must re-authenticate. How should session state be managed for DR resilience?', options: [{ id: 'A', text: 'Increase EC2 instance memory' }, { id: 'B', text: 'Store session state in ElastiCache or DynamoDB — external session stores survive instance failure and regional failover' }, { id: 'C', text: 'Use sticky sessions on the load balancer' }, { id: 'D', text: 'Disable sessions entirely' }], correct: ['B'], explanation: 'Externalized session management (ElastiCache Redis or DynamoDB) decouples sessions from EC2 instances. During failover, sessions persist in the external store (replicated to DR region). Users don\'t lose their sessions even if EC2 instances change.', distractors: { A: 'More memory still loses sessions when the instance is replaced or region fails.', C: 'Sticky sessions bind users to specific instances — if that instance fails, the session is still lost.', D: 'Sessions provide user experience — disabling them is not a practical solution.' } },
  { id: 'd2-dr-034', domain: 2, topics: ['DR', 'S3 versioning', 'backup strategy'], type: 'single', stem: 'A DevOps team accidentally runs a script that deletes all objects in a production S3 bucket. The company needs to recover all objects. What S3 feature was required to have been configured beforehand for recovery?', options: [{ id: 'A', text: 'S3 CRR (Cross-Region Replication)' }, { id: 'B', text: 'S3 versioning — deletion creates delete markers; objects can be recovered by removing delete markers or listing noncurrent versions' }, { id: 'C', text: 'S3 lifecycle rules' }, { id: 'D', text: 'S3 Storage Class Analysis' }], correct: ['B'], explanation: 'With versioning enabled, deleting objects creates delete markers (doesn\'t permanently delete). To recover: delete the delete markers to restore all objects. Without versioning, the objects would be permanently deleted.', distractors: { A: 'CRR replicates to another region — if the script runs, it would also trigger deletion replication (if delete marker replication is enabled). Versioning in the destination prevents permanent loss.', C: 'Lifecycle rules manage object transitions/expiration — not deletion recovery.', D: 'Storage Class Analysis monitors access patterns — not a recovery mechanism.' } },
  { id: 'd2-dr-035', domain: 2, topics: ['DR', 'RTO', 'automation'], type: 'single', stem: 'A company\'s DR runbook requires 20 manual steps, each taking 5-10 minutes, resulting in an RTO of 2-3 hours. How should the RTO be reduced?', options: [{ id: 'A', text: 'Hire more operations staff' }, { id: 'B', text: 'Automate the DR runbook using Systems Manager Automation documents, Lambda, or Step Functions' }, { id: 'C', text: 'Reduce the number of services to simplify DR' }, { id: 'D', text: 'Accept the current RTO' }], correct: ['B'], explanation: 'Automation transforms multi-hour manual DR runbooks into reliable, fast automated processes. AWS Systems Manager Automation, Lambda, and Step Functions can automate failover steps: promote DB replicas, update Route 53, scale up resources, validate health.', distractors: { A: 'More staff speed up parallel execution but automation is fundamentally faster and error-free.', C: 'Simplifying architecture may reduce complexity but automation directly addresses the manual steps causing long RTO.', D: 'Accepting high RTO for critical applications is a business risk — automation is the correct solution.' } },
  { id: 'd2-dr-036', domain: 2, topics: ['DR', 'EKS', 'containerized'], type: 'single', stem: 'A company runs containerized workloads on EKS and needs DR. Container images are stored in ECR in us-east-1. For DR in eu-west-1, what must be done with ECR?', options: [{ id: 'A', text: 'ECR is global — images are available in all regions automatically' }, { id: 'B', text: 'Configure ECR replication (cross-region or cross-account) to copy images to eu-west-1 ECR' }, { id: 'C', text: 'Re-build container images from source in eu-west-1 during failover' }, { id: 'D', text: 'Pull images from us-east-1 ECR from eu-west-1 EKS' }], correct: ['B'], explanation: 'ECR registries are regional. Configure ECR cross-region replication to automatically copy images to eu-west-1. This ensures container images are available locally during failover without cross-region pull delays or dependency on the failed region.', distractors: { A: 'ECR is regional — not automatically global.', C: 'Building images during failover adds significant RTO and may fail if the source code repo is also affected.', D: 'Cross-region ECR pulls work but create a dependency on us-east-1 which may be the failed region.' } },
  { id: 'd2-dr-037', domain: 2, topics: ['DR', 'application recovery controller', 'ARC'], type: 'single', stem: 'A company needs fine-grained control to shift traffic away from an impaired AWS region/AZ during a DR event and to validate readiness before failover. What AWS service provides this?', options: [{ id: 'A', text: 'Route 53 failover routing' }, { id: 'B', text: 'AWS Application Recovery Controller (ARC) — routing control for safe failover with readiness checks' }, { id: 'C', text: 'AWS Auto Scaling' }, { id: 'D', text: 'AWS CloudFormation StackSets' }], correct: ['B'], explanation: 'AWS ARC provides: (1) Routing Control to flip traffic between regions/AZs via Route 53 health checks with safety rules. (2) Readiness Check to verify DR infrastructure is ready before failover. (3) Zonal Shift to quickly move application traffic away from an impaired AZ.', distractors: { A: 'Route 53 failover handles DNS-level routing but lacks ARC\'s safety rules and readiness checks.', C: 'Auto Scaling manages instance counts — not DR routing control.', D: 'CloudFormation StackSets deploys infrastructure to multiple accounts/regions — not DR routing.' } },
  { id: 'd2-dr-038', domain: 2, topics: ['DR', 'cross-region', 'dependency mapping'], type: 'single', stem: 'Before executing a DR failover to a secondary region, which checks should be performed?', options: [{ id: 'A', text: 'Only check that the secondary region EC2 instances are running' }, { id: 'B', text: 'Verify: database replica lag, DR application deployment status, security group/IAM parity, DNS pre-staged, capacity in DR region' }, { id: 'C', text: 'DR failover should proceed immediately without pre-checks to minimize downtime' }, { id: 'D', text: 'Only check Route 53 health checks' }], correct: ['B'], explanation: 'A complete DR readiness check: DB replica status and lag (is data current?), application code deployed in DR, network/security config matches, DNS TTLs lowered, sufficient capacity reserved in DR region. AWS Resilience Hub and ARC Readiness Checks formalize this.', distractors: { A: 'EC2 instances running is only one component — database state, network config, and application deployment must all be verified.', C: 'Proceeding without checks risks failing the failover itself — pre-validation is essential.', D: 'Route 53 health checks are important but insufficient for comprehensive DR readiness.' } },
  { id: 'd2-dr-039', domain: 2, topics: ['DR', 'Config Rules', 'compliance'], type: 'single', stem: 'A company wants to automatically detect when DR best practices are not followed (e.g., no Multi-AZ on RDS, no backup configured for EBS). What service enforces this?', options: [{ id: 'A', text: 'AWS CloudTrail' }, { id: 'B', text: 'AWS Config rules — continuously evaluate resource configuration against DR best practices and alert on deviations' }, { id: 'C', text: 'AWS Inspector' }, { id: 'D', text: 'AWS GuardDuty' }], correct: ['B'], explanation: 'AWS Config managed rules (e.g., rds-multi-az-support, ec2-volume-inuse-check) continuously monitor configuration compliance. Non-compliant resources trigger Config rules, which can auto-remediate or alert via SNS.', distractors: { A: 'CloudTrail logs API calls — not configuration compliance monitoring.', C: 'Inspector scans for security vulnerabilities — not DR configuration compliance.', D: 'GuardDuty detects security threats — not DR configuration gaps.' } },
  { id: 'd2-dr-040', domain: 2, topics: ['DR', 'global accelerator', 'failover'], type: 'single', stem: 'A company needs application-layer failover between regions with very fast traffic rerouting (under 30 seconds) using static IP addresses. What service provides this?', options: [{ id: 'A', text: 'Route 53 with 30-second TTL' }, { id: 'B', text: 'AWS Global Accelerator — static IPs, health-check-based routing, sub-30-second failover over the AWS backbone' }, { id: 'C', text: 'CloudFront with origin failover' }, { id: 'D', text: 'NAT Gateway in DR region' }], correct: ['B'], explanation: 'Global Accelerator provides two static Anycast IPs. Traffic enters the AWS network at the nearest edge. Health checks detect endpoint failures and reroute in seconds. No DNS TTL delays since clients always use the same static IP.', distractors: { A: 'Route 53 with short TTL still has propagation delays — DNS caching is unpredictable. Also clients may ignore TTLs.', C: 'CloudFront origin failover is for CDN origins — not application-level global failover with static IPs.', D: 'NAT Gateway is for outbound internet access — not application failover.' } },
  { id: 'd2-dr-041', domain: 2, topics: ['DR', 'EFS', 'cross-region backup'], type: 'single', stem: 'An EFS file system stores critical application data. For DR, the data must be available in a secondary region. How is EFS data replicated cross-region?', options: [{ id: 'A', text: 'EFS automatically replicates cross-region' }, { id: 'B', text: 'Enable EFS replication — creates and maintains a read-only replica in another region with sub-minute RPO' }, { id: 'C', text: 'Use DataSync to copy EFS data daily' }, { id: 'D', text: 'EFS snapshots can be copied cross-region' }], correct: ['B'], explanation: 'EFS Replication provides continuous, automatic replication to an EFS file system in another region. RPO is typically under a minute. On failover, the replica can be promoted to a standalone writable file system.', distractors: { A: 'EFS is regional — not automatically cross-region.', C: 'DataSync daily copies have RTO of up to 24 hours — not continuous.', D: 'EFS does not have a native snapshot feature like EBS (though AWS Backup can back up EFS).' } },
  { id: 'd2-dr-042', domain: 2, topics: ['DR', 'Neptune', 'Redshift', 'managed service DR'], type: 'single', stem: 'A company uses Amazon Neptune (graph database) in us-east-1. For DR in eu-west-1, what replication option does Neptune support?', options: [{ id: 'A', text: 'Neptune doesn\'t support cross-region DR' }, { id: 'B', text: 'Neptune Global Database — fast cross-region replication with read replicas in secondary regions and managed failover' }, { id: 'C', text: 'DMS continuous replication for Neptune' }, { id: 'D', text: 'Neptune snapshot copy to eu-west-1 (daily)' }], correct: ['B'], explanation: 'Neptune Global Database (similar to Aurora Global Database) provides storage-level replication across regions with <1 second typical lag. Secondary regions serve read traffic and can be promoted to primary on failover.', distractors: { A: 'Neptune does support cross-region DR via Neptune Global Database.', C: 'DMS supports Neptune migration/replication but Neptune Global Database is the native, simpler solution.', D: 'Snapshot copies provide point-in-time recovery but not continuous replication.' } },
  { id: 'd2-dr-043', domain: 2, topics: ['DR', 'multi-region architecture', 'complexity'], type: 'single', stem: 'A company is considering multi-region Active-Active architecture for DR. Which is a significant CHALLENGE of this approach?', options: [{ id: 'A', text: 'Higher costs vs. single-region' }, { id: 'B', text: 'Data consistency and conflict resolution across regions for write operations — distributed transactions are complex' }, { id: 'C', text: 'AWS doesn\'t support multi-region services' }, { id: 'D', text: 'Performance is worse than single-region' }], correct: ['B'], explanation: 'The main challenge with multi-region Active-Active is distributed consistency: if both regions accept writes simultaneously, conflicts can occur. Solutions (DynamoDB last-writer-wins, CRDTs, event sourcing) add significant application complexity.', distractors: { A: 'Higher costs are real but manageable — data consistency is the fundamental engineering challenge.', C: 'AWS explicitly supports and encourages multi-region architectures.', D: 'Performance can actually be better for users near the second region — latency decreases globally.' } },
  { id: 'd2-dr-044', domain: 2, topics: ['DR', 'recovery', 'order of operations'], type: 'single', stem: 'During DR failover, what is the CORRECT order of operations to avoid data corruption?', options: [{ id: 'A', text: '1. Update DNS → 2. Scale up DR resources → 3. Promote database replica' }, { id: 'B', text: '1. Verify DR environment health → 2. Promote database replica → 3. Scale up application tier → 4. Update DNS to DR region' }, { id: 'C', text: '1. Immediately update DNS → 2. Hope DR resources are ready' }, { id: 'D', text: '1. Terminate primary region → 2. Restore from backup → 3. Update DNS' }], correct: ['B'], explanation: 'Safe failover order: First verify DR is ready, then promote the database (making writes possible), then scale application tier (so traffic doesn\'t hit an under-provisioned tier), then update DNS last (direct traffic only when ready). This minimizes user impact.', distractors: { A: 'Updating DNS before the database is promoted and the app is scaled means users hit an unready system.', C: 'Updating DNS without verifying readiness risks directing traffic to a broken environment.', D: 'Terminating primary first prevents rollback and restoring from backup has high RTO.' } },
  { id: 'd2-dr-045', domain: 2, topics: ['DR', 'systems manager', 'parameter store', 'cross-region'], type: 'single', stem: 'An application retrieves configuration from Systems Manager Parameter Store. During DR failover to a secondary region, the application fails because Parameter Store parameters don\'t exist in the secondary region. What should have been configured?', options: [{ id: 'A', text: 'Parameter Store parameters are global and available in all regions' }, { id: 'B', text: 'Replicate Parameter Store parameters to the secondary region — use AWS Config + Lambda automation or SSM cross-region copy scripts' }, { id: 'C', text: 'Hardcode all configuration values in the application' }, { id: 'D', text: 'Use IAM cross-region roles to access the primary region\'s Parameter Store' }], correct: ['B'], explanation: 'Parameter Store is regional. DR preparation must include replicating all parameters to the secondary region. Use automation (EventBridge + Lambda) to sync parameters across regions, or use AWS Backup for Parameter Store.', distractors: { A: 'Parameter Store is regional — not automatically global.', C: 'Hardcoding configuration defeats the purpose of Parameter Store and creates a maintenance nightmare.', D: 'Cross-region Parameter Store access creates a dependency on the primary region — if it fails, the DR region also fails.' } },
]
